    "/api/v1/admin/dashboard/kpis": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /**
         * Filtered dashboard KPIs (live, uncached)
         * @description Live, uncached KPI breakdown for an explicit date window — separate from the cached `/dashboard` snapshot.
         *
         *     **Channel split.** `revenue` and `orders` are each broken into `online`, `manual`, and `combined`:
         *     - `online` — PAID payments, filtered on `Payment.createdAt`.
         *     - `manual` — ManualOrders with `paymentStatus = CONFIRMED`, filtered on `validatedAt`, summing `confirmedAmountPaid`.
         *     - `combined` — online + manual.
         *
         *     **Date filtering by section.** Period-based sections (`revenue`, `orders`, `customers`, `refunds`, `conversations`) respect the selected date window. Current-state sections (`inventory`, `staff`, `catalog`) are a live snapshot, carry `_scope: 'current'`, and intentionally ignore the date filter.
         *
         *     **Section selection.** The optional `sections` query param is a comma-separated list — pass only what the page renders and only those queries run. Omitting it returns all eight sections. Any section NOT requested is ABSENT from the response (the field is optional, not null) — guard with optional chaining on the frontend.
         *
         *     **Period.** One of `today`, `7d`, `30d`, `90d`, `this_month`, `12m`, `custom`. When `period=custom`, both `from` and `to` are required ISO date strings — otherwise 400.
         *
         *     Requires SUPER_ADMIN role.
         */
        get: {
            parameters: {
                query?: {
                    period?: "today" | "7d" | "30d" | "90d" | "this_month" | "12m" | "custom";
                    from?: string;
                    to?: string;
                    sections?: string;
                };
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: never;
            responses: {
                /** @description Filtered KPI breakdown returned. Section fields are present only if requested via ?sections. */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["AdminDashboardKpisResponse"];
                    };
                };
                /** @description Validation error — e.g. 'from'/'to' missing when period is 'custom', or an unknown section name. */
                400: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["AdminErrorResponse"];
                    };
                };
                /** @description SUPER_ADMIN role required. */
                403: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @enum {boolean} */
                            success: false;
                            /** @example Forbidden */
                            message: string;
                        };
                    };
                };
                /** @description Admin API rate limit reached (120 requests/min per staff). */
                429: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @enum {boolean} */
                            success: false;
                            /** @example Admin API rate limit reached. Try again in a moment. */
                            message: string;
                            /** @example 42 */
                            retryAfter: number;
                        };
                    };
                };
            };
        };
        put?: never;
        post?: never;
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
